<!DOCTYPE html>
<html lang="pt">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Relatórios | Gestão de Expedientes</title><link rel="stylesheet" href="assets/css/style.css"></head>
<body class="app-page"><header class="topbar no-print"><a class="topbar-brand" href="dashboard.php"><span>GE</span> Gestão de Expedientes</a><form method="post" action="logout.php"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(getCsrfToken(), ENT_QUOTES, 'UTF-8') ?>"><button class="logout-button" type="submit">Terminar sessão</button></form></header>
<main class="content-shell reports-shell"><div class="page-heading no-print"><div><p class="section-kicker">Análise operacional</p><h1>Relatórios</h1><p class="muted">Informação consolidada dos dados registados no sistema.</p></div><div class="report-actions"><button class="secondary-button" type="button" onclick="window.print()">Imprimir</button><?php if ($data !== null): ?><a class="primary-link" href="<?= htmlspecialchars($csvUrl, ENT_QUOTES, 'UTF-8') ?>">Exportar CSV</a><?php endif; ?></div></div><?php if (isset($errorMessage)): ?><div class="flash error no-print" role="alert"><?= htmlspecialchars($errorMessage, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?>
<?php if ($data !== null): ?><form class="report-filters no-print" method="get" action="relatorios.php"><div><label for="date_from">Data inicial</label><input id="date_from" name="date_from" type="date" value="<?= htmlspecialchars($filters['from'], ENT_QUOTES, 'UTF-8') ?>"></div><div><label for="date_to">Data final</label><input id="date_to" name="date_to" type="date" value="<?= htmlspecialchars($filters['to'], ENT_QUOTES, 'UTF-8') ?>"></div><div><label for="status">Estado</label><select id="status" name="status"><option value="">Todos</option><?php foreach ($statuses as $key => $label): ?><option value="<?= htmlspecialchars($key, ENT_QUOTES, 'UTF-8') ?>" <?= $filters['status'] === $key ? 'selected' : '' ?>><?= htmlspecialchars($label, ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div><label for="user_id">Utilizador</label><select id="user_id" name="user_id"><option value="">Todos</option><?php foreach ($users as $user): ?><option value="<?= (int) $user['id'] ?>" <?= $filters['user_id'] === (int) $user['id'] ? 'selected' : '' ?>><?= htmlspecialchars($user['full_name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div><label for="destination">Setor/destino</label><input id="destination" name="destination" value="<?= htmlspecialchars($filters['destination'], ENT_QUOTES, 'UTF-8') ?>" placeholder="Ex.: Direção"></div><button type="submit">Aplicar filtros</button></form>
<section class="report-summary"><div class="metric-card"><span>Total de expedientes</span><strong><?= $data['summary']['total'] ?></strong></div><div class="metric-card"><span>Em tramitação</span><strong><?= $data['summary']['in_progress'] ?></strong></div><div class="metric-card"><span>Concluídos</span><strong><?= $data['summary']['completed'] ?></strong></div><div class="metric-card"><span>Arquivados</span><strong><?= $data['summary']['archived'] ?></strong></div><div class="metric-card"><span>Tramitações</span><strong><?= $data['summary']['tramitation_count'] ?></strong></div><div class="metric-card"><span>Despachos</span><strong><?= $data['summary']['dispatch_count'] ?></strong></div><div class="metric-card"><span>Eventos de auditoria</span><strong><?= $data['summary']['audit_count'] ?></strong></div></section>
<div class="report-grid"><section class="report-panel"><h2>Expedientes por estado</h2><div class="bar-chart"><?php foreach ($data['by_status'] as $row): ?><div class="bar-row"><span><?= htmlspecialchars($statuses[$row['status']] ?? $row['status'], ENT_QUOTES, 'UTF-8') ?></span><div><i style="width: <?= $data['summary']['total'] ? round(((int) $row['total'] / $data['summary']['total']) * 100) : 0 ?>%"></i></div><strong><?= (int) $row['total'] ?></strong></div><?php endforeach; ?><?php if (!$data['by_status']): ?><p class="empty-state">Sem dados para o período.</p><?php endif; ?></div></section><section class="report-panel"><h2>Expedientes por período</h2><table><thead><tr><th>Data</th><th>Total</th></tr></thead><tbody><?php foreach ($data['by_period'] as $row): ?><tr><td><?= htmlspecialchars(date('d/m/Y', strtotime($row['period_date'])), ENT_QUOTES, 'UTF-8') ?></td><td><?= (int) $row['total'] ?></td></tr><?php endforeach; ?><?php if (!$data['by_period']): ?><tr><td colspan="2" class="empty-state">Sem dados para o período.</td></tr><?php endif; ?></tbody></table></section></div>
<section class="report-panel"><h2>Expedientes arquivados</h2><div class="table-wrap"><table><thead><tr><th>Número</th><th>Assunto</th><th>Referência</th><th>Arquivado por</th><th>Data</th></tr></thead><tbody><?php foreach ($data['archived'] as $row): ?><tr><td><?= htmlspecialchars($row['reference_code'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['subject'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['archive_reference'] ?: '-', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['archived_by_name'] ?? 'Utilizador removido', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars(date('d/m/Y H:i', strtotime($row['archived_at'])), ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; ?><?php if (!$data['archived']): ?><tr><td colspan="5" class="empty-state">Nenhum expediente arquivado.</td></tr><?php endif; ?></tbody></table></div></section>
<div class="report-grid"><section class="report-panel"><h2>Tramitações realizadas</h2><table><thead><tr><th>Destino</th><th>Total</th></tr></thead><tbody><?php foreach ($data['tramitacoes'] as $row): ?><tr><td><?= htmlspecialchars($row['destination'], ENT_QUOTES, 'UTF-8') ?></td><td><?= (int) $row['total'] ?></td></tr><?php endforeach; ?><?php if (!$data['tramitacoes']): ?><tr><td colspan="2" class="empty-state">Sem tramitações.</td></tr><?php endif; ?></tbody></table></section><section class="report-panel"><h2>Despachos registados</h2><table><thead><tr><th>Estado</th><th>Total</th></tr></thead><tbody><?php foreach ($data['despachos'] as $row): ?><tr><td><?= htmlspecialchars(ucfirst($row['status']), ENT_QUOTES, 'UTF-8') ?></td><td><?= (int) $row['total'] ?></td></tr><?php endforeach; ?><?php if (!$data['despachos']): ?><tr><td colspan="2" class="empty-state">Sem despachos.</td></tr><?php endif; ?></tbody></table></section></div>
<div class="report-grid"><section class="report-panel"><h2>Atividades dos utilizadores</h2><table><thead><tr><th>Utilizador</th><th>Ações</th></tr></thead><tbody><?php foreach ($data['user_activity'] as $row): ?><tr><td><?= htmlspecialchars($row['user_name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= (int) $row['total'] ?></td></tr><?php endforeach; ?><?php if (!$data['user_activity']): ?><tr><td colspan="2" class="empty-state">Sem atividades.</td></tr><?php endif; ?></tbody></table></section><section class="report-panel"><h2>Eventos de auditoria</h2><table><thead><tr><th>Ação</th><th>Entidade</th><th>Total</th></tr></thead><tbody><?php foreach ($data['audit_events'] as $row): ?><tr><td><?= htmlspecialchars($row['action'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['entity_type'], ENT_QUOTES, 'UTF-8') ?></td><td><?= (int) $row['total'] ?></td></tr><?php endforeach; ?><?php if (!$data['audit_events']): ?><tr><td colspan="3" class="empty-state">Sem eventos.</td></tr><?php endif; ?></tbody></table></section></div><?php endif; ?></main></body></html>